SELECT learner, COALESCE(level, '') AS level, COALESCE(category, '') AS category, COALESCE(current_no, '') AS current_no, COALESCE(answered, 0) AS answered, COALESCE(right_count, 0) AS right_count, COALESCE(asked_nos, '') AS asked_nos, COALESCE(asked_count, 0) AS asked_count, COALESCE(mode, '') AS mode, COALESCE(lesson_code, '') AS lesson_code, COALESCE(round_start_id, 0) AS round_start_id, COALESCE(seq, 0) AS seq, COALESCE(last_correct, 0) AS last_correct FROM quiz_progress WHERE learner = :learner AND subject_id = CAST(:subject_id AS INTEGER)
